use serde_json::{Value, json};
use std::io;
fn main() {
    let inputs: Vec<Value> = serde_json::from_reader(io::stdin().lock()).unwrap();
    let outputs:Vec<Value>=inputs.into_iter().map(|i|{let asset=d2_rs_math::svg_image::RasterAsset{mime:i["MIME"].as_str().unwrap().to_owned(),data:i["Data"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as u8).collect(),width:i["Width"].as_i64().unwrap(),height:i["Height"].as_i64().unwrap(),decoded_bytes:i["DecodedBytes"].as_i64().unwrap()};let token=d2_rs_core::CancellationToken::new();let c=match i["Cancel"].as_str().unwrap(){"cancelled"=>{token.cancel();Some(&token)},"deadline"=>{token.expire();Some(&token)},_=>None};let mut out=json!({"Format":"","DecodedBytes":0,"Error":"","Width":0,"Height":0,"Pixels":[]});if i["Mode"]=="prepare"{match d2_rs_export::raster_asset_validation::prepare_jpeg(i["ID"].as_str().unwrap(),&asset,i["Available"].as_i64().unwrap(),c){Err(e)=>out["Error"]=json!(e),Ok((data,charge))=>{let mut r=png::Decoder::new(std::io::Cursor::new(data)).read_info().unwrap();let mut b=vec![0;r.output_buffer_size().unwrap()];let frame=r.next_frame(&mut b).unwrap();let pixels:Vec<[u16;4]>=b[..frame.buffer_size()].as_chunks::<8>().0.iter().map(|p|std::array::from_fn(|j|u16::from_be_bytes([p[2*j],p[2*j+1]]))).collect();out=json!({"Format":"jpeg","DecodedBytes":charge,"Error":"","Width":frame.width,"Height":frame.height,"Pixels":pixels});}}}else{match d2_rs_export::raster_asset_validation::validate_static(i["ID"].as_str().unwrap(),&asset,i["Available"].as_i64().unwrap(),c){Err(e)=>out["Error"]=json!(e),Ok(v)=>{out["Format"]=json!(v.format);out["DecodedBytes"]=json!(v.decoded_bytes);}}}out}).collect();
    serde_json::to_writer(io::stdout().lock(), &outputs).unwrap();
}
